package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Real;
    in attribute io_1 : Boolean;
    attribute running : Boolean := false;
    attribute previousPressed : Boolean := false;
    attribute periodMs : Integer := 500;
    attribute blinkPhase : Integer := 0;
    perform action tick {
      first start;
      then if io_1 and not previousPressed {
        first start;
        then assign running := not running;
        then assign blinkPhase := 0;
      }
      then assign previousPressed := io_1;
      then assign periodMs := (if RealFunctions::floor(io_0) <= 0 ? 1 else (if RealFunctions::floor(io_0) >= 2000 ? 2000 else RealFunctions::floor(io_0)));
      then if running {
        first start;
        then assign blinkPhase := blinkPhase + 10;
      }
      then if running and blinkPhase >= periodMs {
        first start;
        then assign blinkPhase := blinkPhase - periodMs;
      }
    }
    out attribute io_2 : Boolean = running and blinkPhase < (periodMs / 2);
    out attribute io_3 : Integer = periodMs;
  }
  part system : Controller;
}
